    pub fn claim_active_trainer_battle_rewards(
        &self,
        state: &mut GameState,
        time_of_day: TimeOfDay,
    ) -> Result<BattleRewardOutcome> {
        let mut staged_state = state.clone();
        let level_up_happiness = self.level_up_happiness_context(&staged_state)?;
        let outcome = core_claim_active_trainer_battle_rewards(
            &mut staged_state,
            &self.battle_reward_rules,
            &self.pokemon,
            &self.moves,
            &self.learnsets,
            &self.growth_rates,
            &self.evolutions,
            &self.battle_stat_multipliers,
            level_up_happiness,
            time_of_day,
        )
        .map_err(|error| anyhow::anyhow!("claim trainer battle rewards: {error:?}"))?;
        *state = staged_state;
        Ok(outcome)
    }

    pub fn claim_active_trainer_battle_rewards_now(
        &self,
        state: &mut GameState,
    ) -> Result<BattleRewardOutcome> {
        self.claim_active_trainer_battle_rewards(state, state.time.time_of_day)
    }

    pub fn claim_active_wild_battle_rewards<S>(
        &self,
        state: &mut GameState,
        time_of_day: TimeOfDay,
        divider: &mut S,
    ) -> Result<BattleRewardOutcome>
    where
        S: DividerSource + ?Sized,
        S::Error: std::fmt::Display,
    {
        let mut staged_state = state.clone();
        let level_up_happiness = self.level_up_happiness_context(&staged_state)?;
        let battle_end = self.active_battle_end_context(&staged_state)?;
        let pay_day_money = self.active_battle_pay_day_payout(&staged_state);
        self.claim_active_battle_pay_day_money(&mut staged_state, pay_day_money)?;
        let outcome = core_claim_active_wild_battle_rewards(
            &mut staged_state,
            &self.battle_reward_rules,
            &self.pokemon,
            &self.moves,
            &self.learnsets,
            &self.growth_rates,
            &self.evolutions,
            level_up_happiness,
            time_of_day,
            divider,
        )
        .map_err(|error| anyhow::anyhow!("claim wild battle rewards: {error:?}"))?;
        if matches!(staged_state.battle, BattleMemory::Inactive)
            && let Some((battle_type, roaming_slot, enemy, map_name)) = battle_end
        {
            self.finish_battle_roaming_update_exact(
                &mut staged_state,
                &battle_type,
                roaming_slot,
                &enemy,
                &map_name,
                divider,
            )?;
        }
        if let Some(terminal) = staged_state.pending_static_wild_terminal.as_mut() {
            terminal.win_cleanup_applied = true;
        }
        *state = staged_state;
        Ok(outcome)
    }

    pub fn level_up_happiness_context(
        &self,
        state: &GameState,
    ) -> Result<BattleLevelUpHappinessContext> {
        let map_name = match &state.overworld {
            crystal_core::state::OverworldMemory::Active { map_name, .. } => map_name,
            crystal_core::state::OverworldMemory::Inactive => match &state.battle {
                BattleMemory::Wild { map_name, .. } => map_name,
                BattleMemory::StaticWild { .. }
                | BattleMemory::Trainer { .. }
                | BattleMemory::Inactive => {
                    anyhow::bail!("level-up happiness requires an active map")
                }
            },
        };
        let current_landmark = u8::try_from(self.pokegear_landmark_for_map(map_name)?.id)
            .with_context(|| format!("battle map {map_name} landmark exceeds one byte"))?;
        Ok(BattleLevelUpHappinessContext {
            current_landmark,
            gain_level: self.happiness_change("HAPPINESS_GAINLEVEL")?,
            gain_level_at_home: self.happiness_change("HAPPINESS_GAINLEVELATHOME")?,
        })
    }

    pub fn happiness_change(&self, code: &str) -> Result<[i16; 3]> {
        self.happiness_data
            .as_ref()
            .context("item and battle rewards require exported happiness changes")?
            .changes
            .values()
            .find(|entry| entry.code == code)
            .with_context(|| format!("happiness changes missing {code}"))
            .map(|entry| [entry.low, entry.mid, entry.high])
    }

    pub fn claim_active_wild_battle_rewards_now<S>(
        &self,
        state: &mut GameState,
        divider: &mut S,
    ) -> Result<BattleRewardOutcome>
    where
        S: DividerSource + ?Sized,
        S::Error: std::fmt::Display,
    {
        self.claim_active_wild_battle_rewards(state, state.time.time_of_day, divider)
    }

    fn claim_active_battle_pay_day_money(&self, state: &mut GameState, amount: u32) -> Result<()> {
        if amount == 0 {
            return Ok(());
        }
        let max_money = self
            .currency_constants
            .get("MAX_MONEY")
            .context("currency constants missing MAX_MONEY")?;
        state.money = state.money.saturating_add(amount).min(max_money);
        state.battle_pay_day_money = 0;
        Ok(())
    }

    fn active_battle_pay_day_payout(&self, state: &GameState) -> u32 {
        let amount = state.battle_pay_day_money.min(0x00ff_ffff);
        if state.battle_amulet_coin_active {
            amount.saturating_mul(2).min(0x00ff_ffff)
        } else {
            amount
        }
    }

    fn active_battle_pay_day_money_after_turn(
        &self,
        state: &GameState,
        outcome: &BattleTurnOutcome,
    ) -> u32 {
        let amount = state.battle_pay_day_money.wrapping_add(
            outcome
                .events
                .iter()
                .filter_map(|event| match event {
                    BattleEvent::PayDayMoney { amount, .. } => Some(*amount),
                    _ => None,
                })
                .fold(0_u32, u32::wrapping_add),
        ) & 0x00ff_ffff;
        if state.battle_amulet_coin_active {
            amount.saturating_mul(2).min(0x00ff_ffff)
        } else {
            amount
        }
    }

    pub fn fishing_rod_item(&self, item_id: &str) -> Result<(&Item, &str)> {
        let item = self.item(item_id)?;
        let rod = fishing_rod_for_item_id(&self.fishing, item_id).with_context(|| {
            format!(
                "field fishing rod item {item_id} is not declared by exact fishing rod item rules"
            )
        })?;
        Ok((item, rod))
    }

    pub fn field_fishing_rod(&self, state: &GameState, item_id: &str) -> Result<String> {
        let (item, rod) = self.fishing_rod_item(item_id)?;
        if !item.field_usable {
            anyhow::bail!("field fishing rod item {item_id} is not usable in the field");
        }
        if !state.bag.has_item(item) {
            anyhow::bail!("field fishing rod item {item_id} is not in the bag");
        }
        Ok(rod.to_string())
    }

    pub fn cast_fishing_rod_in_session_with_divider<S>(
        &self,
        state: &mut GameState,
        session: &OverworldSession,
        rod: &str,
        divider: &mut S,
    ) -> Result<FishingCastOutcome>
    where
        S: DividerSource + ?Sized,
        S::Error: std::fmt::Display,
    {
        self.require_no_active_battle(state, "fishing rod")?;
        if matches!(
            session.player.mode,
            MovementMode::Surf | MovementMode::SurfPika
        ) {
            anyhow::bail!(crystal_core::world::fishing::FishingError::CannotFishWhileSurfing);
        }
        let target = checked_move_by_stride(
            session.player.tile,
            session.player.facing,
            StepOptions::default().stride_tiles,
        )
        .ok_or_else(|| {
            anyhow::Error::new(crystal_core::world::fishing::FishingError::FacingTileOutOfBounds)
        })?;
        let sample = sample_collision(&session.map, &session.tileset, target).ok_or_else(|| {
            anyhow::Error::new(crystal_core::world::fishing::FishingError::FacingTileOutOfBounds)
        })?;
        if describe_collision(sample.permission).terrain != Terrain::Water {
            anyhow::bail!(crystal_core::world::fishing::FishingError::FacingTileIsNotWater);
        }

        let mut next_state = state.clone();
        let map_name = session.map.name.clone();
        let group = self.map_fishing_group(&map_name)?;
        let time_of_day = next_state.time.time_of_day;
        let mut rng = CrystalRandom::new(next_state.random_state, divider);
        let rolled = core_do_fishing_exact(
            &mut next_state,
            &self.fishing,
            group,
            rod,
            time_of_day,
            &mut rng,
        )
        .map_err(|error| anyhow::anyhow!("cast fishing rod {rod} on {map_name}: {error}"))?;
        let mut fishing_session = rolled.session;
        let bite_frame = fishing_session
            .start_frame
            .saturating_add(fishing_session.cast_frames)
            .saturating_add(fishing_session.bite_delay_frames);
        let bite = fishing_bite(&mut next_state, &mut fishing_session, bite_frame);
        let wild_battle = if bite == Some(true) {
            fishing_battle_trigger(&mut next_state);
            if let Some(encounter) = fishing_session.outcome.encounter.clone() {
                Some(
                    self.start_fishing_battle_with_rng(
                        &mut next_state,
                        &map_name,
                        session.player.tile,
                        encounter,
                        time_of_day,
                        rolled.bite_roll,
                        rolled
                            .slot_roll
                            .context("fishing bite is missing its slot roll")?,
                        &mut rng,
                    )?,
                )
            } else {
                None
            }
        } else {
            None
        };
        next_state.random_state = rng.state();
        *state = next_state;
        Ok(FishingCastOutcome {
            session: fishing_session,
            bite,
            wild_battle,
        })
    }

    pub fn use_bag_fishing_rod_in_field_with_divider<S>(
        &self,
        state: &mut GameState,
        session: &OverworldSession,
        item_id: &str,
        divider: &mut S,
    ) -> Result<FishingRodItemUseOutcome>
    where
        S: DividerSource + ?Sized,
        S::Error: std::fmt::Display,
    {
        self.require_no_active_battle(state, "field fishing rod item")?;
        let rod = self.field_fishing_rod(state, item_id)?;
        let mut next_state = state.clone();
        let cast =
            self.cast_fishing_rod_in_session_with_divider(&mut next_state, session, &rod, divider)?;
        let cast_state_checksum =
            game_state_checksum(&next_state).context("checksum field fishing rod cast")?;
        let item_use = self.use_bag_item(&mut next_state, item_id, ItemUseContext::Field)?;
        *state = next_state;
        Ok(FishingRodItemUseOutcome {
            item_use,
            rod,
            cast,
            cast_state_checksum,
        })
    }

